<script setup>
import { computed, inject, ref } from 'vue';
import VoteTrendChart from '../../components/VoteTrendChart.vue';
import EngagementReportModal from '../components/reports/V2EngagementReportModal.vue';
import V2Dialog from '../components/shared/V2Dialog.vue';
import EventMatchChat from '../components/events/EventMatchChat.vue';
const props = defineProps({ section: { type: String, required: true } });
const c = inject('admin-v2');
const query = ref('');
const chatEvent = ref(null);
const visibleHistory = computed(() => c.eventHistory.filter(entry => `${entry.title} ${entry.location} ${c.formatHistoryDate(entry.startDatetime)}`.toLowerCase().includes(query.value.toLowerCase())));
const sponsorMetrics = data => data ? [
  ['Utenti totali', data.totalUsersLabel], ['Utenti che hanno visto la sezione', data.seenUsersLabel],
  ['Sezione vista', data.seenRateLabel], ['Tempo medio di visione', data.averageWatchTimeLabel],
  ['Utenti che hanno guardato', data.watchedUsersLabel], ['Tempo di visione totale', data.totalWatchTimeLabel],
  ['Click totali', data.totalClicksLabel], ['Tasso di click', data.clickRateLabel],
  ['Utenti che hanno cliccato', data.uniqueClickersLabel], ['Sponsor più visualizzato', data.topSponsorName],
  ['Visualizzazioni dello sponsor principale', data.topSponsorViewsLabel],
].filter(([, value]) => value !== undefined) : [];
const engagementMetrics = data => data ? [
  ['Tempo totale post voto', data.totalLabel], ['Tempo medio post voto', data.averageLabel], ['Utenti tracciati', data.usersLabel],
  ['Aperture andamento voti', data.voteTrendOpensLabel], ['Aperture selfie', data.selfieOpensLabel], ['Selfie abbandonati', data.selfieAbandonsLabel],
  ['Aperture gioco riflessi', data.reactionOpensLabel], ['Giochi riflessi abbandonati', data.reactionAbandonsLabel], ['Aperture esperienza', data.experienceOpensLabel],
  ['Esperienze abbandonate', data.experienceAbandonsLabel], ['Aperture modifica foto', data.photoEditOpensLabel], ['Aperture modifica voto', data.voteEditOpensLabel],
  ['Modifiche voto abbandonate', data.voteEditAbandonsLabel], ['Voti modificati', data.voteEditCompletionsLabel],
].filter(([, value]) => value !== undefined) : [];
const analyticsMetrics = data => data ? [
  ['Sessioni uniche', data.labels.uniqueSessions], ['Eventi tracciati', data.labels.totalEvents], ['Voti inviati', data.labels.votesSubmitted],
  ['Conversione voto', data.labels.voteConversionRate], ['Feedback inviati', data.labels.feedbackSubmitted], ['Click sponsor', data.labels.sponsorClicks],
  ['Ordini bar completati', data.labels.barOrdersCompleted], ['Eventi per sessione', data.labels.avgEventsPerSession], ['Completamento voto', data.labels.voteCompletionRate], ['Completamento feedback', data.labels.feedbackCompletionRate], ['Completamento ordini bar', data.labels.barOrderCompletionRate],
] : [];
const numbers = value => Number(value || 0).toLocaleString('it-IT');
const purge = () => c.run('purge-event', c.confirmPurge);
</script>

<template>
  <div class="v2-stack v2-insights">
    <template v-if="section === 'results'">
      <section class="v2-panel"><div class="v2-toolbar"><label class="v2-field v2-grow">Evento<select v-model.number="c.selectedResultsEventId" :disabled="!c.availableEvents.length"><option :value="0" disabled>Seleziona un evento</option><option v-for="event in c.availableEvents" :key="event.id" :value="event.id">{{ c.eventLabel(event) }}</option></select></label><button class="v2-button" :disabled="c.isLoadingResults || !c.selectedResultsEventId" @click="c.run('refresh-results', () => c.fetchEventResults({ showLoader: true }))">{{ c.isLoadingResults ? 'Aggiornamento…' : 'Aggiorna risultati' }}</button></div><p class="v2-muted">Aggiornamento automatico ogni 5 secondi.<template v-if="c.lastResultsUpdateLabel"> Ultimo aggiornamento alle {{ c.lastResultsUpdateLabel }}.</template></p></section>
      <p v-if="c.resultsError" class="v2-error" role="alert">{{ c.resultsError }}</p><p v-if="!c.availableEvents.length" class="v2-empty">Crea un evento per vedere i risultati delle votazioni.</p>
      <template v-else><section class="v2-panel"><div class="v2-section-heading"><div><h2>{{ c.selectedResultsEventLabel || 'Classifica MVP' }}</h2><p class="v2-muted">{{ c.selectedResultsEventDate }}</p></div><span class="v2-badge">{{ c.totalVotes }} voti totali</span></div><p v-if="c.isLoadingResults" role="status">Caricamento della classifica…</p><p v-else-if="!c.hasResultsVotes" class="v2-empty">Questo evento non ha ancora ricevuto voti.</p><ol v-if="c.resultsLeaderboard.length" class="v2-leaderboard" aria-live="polite"><li v-for="(entry, index) in c.resultsLeaderboard" :key="entry.id"><span class="v2-rank">{{ String(index + 1).padStart(2, '0') }}</span><div class="v2-grow"><strong>{{ entry.fullName }}</strong><div class="v2-progress" aria-hidden="true"><span :style="{ width: `${entry.percentage}%` }" /></div></div><strong>{{ entry.votes }} <small>{{ entry.votes === 1 ? 'voto' : 'voti' }}</small></strong></li></ol></section>
      <section v-if="!c.isStaff" class="v2-panel"><h2>Impatto degli sponsor</h2><p v-if="c.sponsorAnalyticsError" role="alert" class="v2-error">{{ c.sponsorAnalyticsError }}</p><p v-else-if="c.isLoadingSponsorAnalytics" role="status">Caricamento delle statistiche sponsor…</p><p v-else-if="!c.hasSponsorAnalyticsData" class="v2-empty">Le statistiche sponsor non sono ancora disponibili.</p><template v-else><dl class="v2-metric-grid"><div v-for="[label, value] in sponsorMetrics(c.sponsorAnalyticsDisplay)" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></div></dl><div v-if="c.sponsorChartRows.length" class="v2-table-wrap"><table class="v2-table"><caption>Andamento delle interazioni</caption><thead><tr><th scope="col">Orario</th><th scope="col">Visualizzazioni</th><th scope="col">Click</th></tr></thead><tbody><tr v-for="point in c.sponsorChartRows" :key="point.timestamp || point.label"><th scope="row">{{ point.label }}</th><td>{{ numbers(point.seen) }}<span class="v2-inline-bar" :style="{ width: `${point.seenPercent}%` }" /></td><td>{{ numbers(point.clicks) }}<span class="v2-inline-bar v2-inline-bar--green" :style="{ width: `${point.clicksPercent}%` }" /></td></tr></tbody></table></div></template></section></template>
    </template>

    <template v-else-if="section === 'selfies'">
      <section class="v2-panel"><div class="v2-toolbar"><label class="v2-field v2-grow">Evento<select v-model.number="c.selectedSelfieEventId"><option v-if="!c.availableEvents.length" :value="0" disabled>Nessun evento disponibile</option><option v-for="event in c.availableEvents" :key="event.id" :value="event.id">{{ c.eventLabel(event) }} · {{ c.formatEventDate(event.start_datetime) }}</option></select></label><button class="v2-button" :disabled="c.isLoadingSelfies || !c.selectedSelfieEventId" @click="c.run('refresh-selfies', () => c.loadEventSelfies(c.selectedSelfieEventId))">Aggiorna foto</button></div><p class="v2-muted">Controlla le immagini inviate dai tifosi ed elimina i contenuti da rimuovere.</p></section><p v-if="c.selfieModerationMessage" class="v2-success" role="status">{{ c.selfieModerationMessage }}</p><p v-if="c.selfieLoadError" class="v2-error" role="alert">{{ c.selfieLoadError }}</p><p v-if="c.isLoadingSelfies" role="status" class="v2-panel">Caricamento foto…</p><p v-else-if="!c.eventSelfies.length" class="v2-empty">{{ c.availableEvents.length ? 'Nessuna foto ricevuta per questo evento.' : 'Crea un evento per raccogliere i selfie dei tifosi.' }}</p><div v-else class="v2-selfie-grid"><article v-for="selfie in c.eventSelfies" :key="selfie.id" class="v2-panel v2-selfie-card"><a v-if="selfie.image_src" :href="selfie.image_src" target="_blank" rel="noopener noreferrer" :aria-label="`Apri il selfie ${selfie.id} in una nuova scheda`"><img :src="selfie.image_src" :alt="selfie.caption || `Selfie ${selfie.id}`" loading="lazy" /></a><div v-else class="v2-selfie-missing">Immagine non disponibile</div><div class="v2-selfie-body"><div class="v2-section-heading"><h2>{{ selfie.caption || 'Senza didascalia' }}</h2><span class="v2-badge">{{ c.selfieStatusLabel(selfie) }}</span></div><dl class="v2-data-list"><div><dt>Inviato</dt><dd>{{ c.formatSelfieDate(selfie.submitted_at) || 'N/D' }}</dd></div><div><dt>Dispositivo</dt><dd>{{ selfie.device_token || 'Non disponibile' }}</dd></div><div><dt>Dimensione</dt><dd>{{ c.formatSelfieFileSize(selfie.file_size_bytes) || 'N/D' }}</dd></div><div><dt>Consenso immagine</dt><dd>{{ selfie.accepted_image_terms ? 'Accettato' : 'Non indicato' }}</dd></div></dl><button class="v2-button v2-danger" :disabled="c.isSelfieBusy(selfie.id)" @click="c.confirmAction('Eliminare questa foto?', 'Il selfie verrà rimosso dall’evento.', () => c.run(`delete-selfie-${selfie.id}`, () => c.deleteSelfie(selfie)))">{{ c.isSelfieBusy(selfie.id) ? 'Eliminazione…' : 'Elimina foto' }}</button></div></article></div>
    </template>

    <template v-else-if="section === 'history'">
      <section class="v2-panel"><div class="v2-toolbar"><label class="v2-field v2-grow">Cerca nello storico<input v-model="query" type="search" placeholder="Squadra, luogo o data…" /></label><button class="v2-button" :disabled="c.isLoadingEventHistory" @click="c.run('history-refresh', c.refreshEventHistory)">{{ c.isLoadingEventHistory ? 'Aggiornamento…' : 'Aggiorna storico' }}</button></div><p class="v2-muted">Risultati, dati di engagement e report degli eventi conclusi.</p></section><p v-if="c.eventHistorySuccess" class="v2-success" role="status">{{ c.eventHistorySuccess }}</p><p v-if="c.eventHistoryError" class="v2-error" role="alert">{{ c.eventHistoryError }}</p><p v-if="c.isLoadingEventHistory" class="v2-panel" role="status">Caricamento dello storico…</p><p v-else-if="!visibleHistory.length" class="v2-empty">{{ c.eventHistory.length ? 'Nessun evento corrisponde alla ricerca.' : 'Gli eventi conclusi compariranno qui.' }}</p>
      <details v-for="entry in visibleHistory" :key="entry.id" class="v2-panel v2-history-event"><summary><span><strong>{{ entry.title }}</strong><small>{{ c.formatHistoryDate(entry.startDatetime) }}<template v-if="entry.location"> · {{ entry.location }}</template></small></span><span class="v2-badge">{{ entry.totalVotesLabel }} voti</span></summary><div class="v2-stack v2-history-content"><div class="v2-toolbar"><button class="v2-button v2-primary" @click="c.openEngagementReport(entry)">Prepara report PDF</button><button class="v2-button" :disabled="c.isGeneratingHistoryAiReport(entry.id)" @click="c.run(`history-ai-${entry.id}`, () => c.generateEventAiReport(entry))">{{ c.isGeneratingHistoryAiReport(entry.id) ? 'Analisi in corso…' : entry.aiReport ? 'Rigenera report AI' : 'Genera report AI' }}</button><button type="button" class="v2-button" :aria-expanded="chatEvent === entry.id" @click="chatEvent = chatEvent === entry.id ? null : entry.id">{{ chatEvent === entry.id ? 'Chiudi Match Chat' : 'Match Chat' }}</button><button v-if="c.isSuperAdmin" class="v2-button v2-danger" @click="c.openPurgeDialog(entry)">Elimina evento</button></div><dl class="v2-metric-grid"><div><dt>Voti totali</dt><dd>{{ entry.totalVotesLabel }}</dd></div><div><dt>Visitatori totali</dt><dd>{{ entry.totalVisitorsLabel }}</dd></div><div><dt>Visitatori unici</dt><dd>{{ entry.uniqueVisitorsLabel }}</dd></div><div><dt>Click sponsor</dt><dd>{{ entry.sponsorClicksTotalLabel }}</dd></div></dl>

      <EventMatchChat v-if="chatEvent === entry.id" :key="entry.id" :event="entry" />
      <section class="v2-history-section"><h3>MVP e premi</h3><p v-if="entry.mvp"><strong>{{ entry.mvp.name }}</strong> · {{ numbers(entry.mvp.votes) }} voti</p><p v-else class="v2-muted">Nessun MVP assegnato.</p><p><span class="v2-badge">{{ entry.hasPrizeDraw ? 'Estrazione eseguita' : 'Estrazione non eseguita' }}</span></p><ul v-if="entry.prizes.length" class="v2-simple-list"><li v-for="prize in entry.prizes" :key="prize.id"><strong>{{ prize.name }}</strong><span>{{ prize.hasWinner ? `Codice vincente: ${prize.winnerTicketCode}` : 'Codice non assegnato' }}</span></li></ul><p v-else class="v2-muted">Nessun premio configurato.</p></section>

      <details v-if="entry.aiReport" class="v2-history-section" open><summary>Analisi AI post partita</summary><div class="v2-stack v2-detail-body"><p>{{ entry.aiReport.executiveSummary }}</p><p v-if="entry.aiReport.fullReport" class="v2-preserve-lines">{{ entry.aiReport.fullReport }}</p><div class="v2-grid v2-grid-2"><section v-for="[key, label] in [['strengths', 'Punti forti'], ['criticalities', 'Criticità'], ['insights', 'Insight'], ['suggestions', 'Azioni suggerite']]" :key="key"><template v-if="entry.aiReport[key]?.length"><h4>{{ label }}</h4><ul><li v-for="(item, index) in entry.aiReport[key]" :key="index">{{ item }}</li></ul></template></section></div></div></details>

      <details class="v2-history-section"><summary>Interazioni sponsor</summary><div class="v2-stack v2-detail-body"><dl v-if="entry.sponsorAnalyticsHasData" class="v2-metric-grid"><div v-for="[label, value] in sponsorMetrics(entry.sponsorAnalyticsDisplay)" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></div></dl><ul v-if="entry.sponsorClicks.length" class="v2-simple-list"><li v-for="sponsor in entry.sponsorClicks" :key="sponsor.id"><strong>{{ sponsor.reportName || sponsor.name }}</strong><span>{{ numbers(sponsor.clicks) }} click</span></li></ul><p v-else class="v2-muted">Nessun click registrato.</p><div v-if="entry.sponsorAnalyticsTimeline.length" class="v2-table-wrap"><table class="v2-table"><caption>Andamento interazioni sponsor</caption><thead><tr><th scope="col">Orario</th><th scope="col">Viste</th><th scope="col">Guardate</th><th scope="col">Click</th></tr></thead><tbody><tr v-for="point in entry.sponsorAnalyticsTimeline" :key="point.timestamp || point.label"><th scope="row">{{ point.label }}</th><td>{{ numbers(point.seen) }}</td><td>{{ numbers(point.watched) }}</td><td>{{ numbers(point.clicks) }}</td></tr></tbody></table></div></div></details>

      <details class="v2-history-section"><summary>Sondaggio e suggerimenti</summary><div class="v2-stack v2-detail-body"><template v-if="entry.feedbackSummary"><p class="v2-muted">{{ entry.feedbackSummary.totalResponsesLabel }}</p><section v-for="question in entry.feedbackSummary.questions" :key="question.id"><h4>{{ question.title }}</h4><ul class="v2-simple-list"><li v-for="answer in question.answers" :key="answer.value"><span>{{ answer.label }}</span><strong>{{ answer.countLabel }}<template v-if="entry.feedbackSummary.hasResponses"> ({{ answer.percentLabel }})</template></strong></li></ul></section><section v-if="entry.feedbackSummary.suggestionQuestion"><h4>{{ entry.feedbackSummary.suggestionQuestion.title }}</h4><ul v-if="entry.feedbackSummary.suggestionQuestion.answers?.length"><li v-for="(answer, index) in entry.feedbackSummary.suggestionQuestion.answers" :key="index">{{ typeof answer === 'string' ? answer : answer.text || answer.value }}</li></ul><ul v-else-if="entry.feedbackSummary.suggestionQuestion.suggestions?.length"><li v-for="(answer, index) in entry.feedbackSummary.suggestionQuestion.suggestions" :key="index">{{ typeof answer === 'string' ? answer : answer.text }}</li></ul><p v-else class="v2-muted">Nessun suggerimento disponibile.</p></section></template><p v-else class="v2-muted">Nessuna risposta registrata.</p></div></details>

      <details class="v2-history-section"><summary>Permanenza ed esperienze post voto</summary><div class="v2-detail-body"><dl v-if="entry.engagement" class="v2-metric-grid"><div v-for="[label, value] in engagementMetrics(entry.engagement)" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></div></dl><p v-if="!entry.engagement?.hasData" class="v2-muted">Nessun dato di permanenza registrato.</p></div></details>

      <details class="v2-history-section"><summary>Analytics, conversioni e segmenti</summary><div class="v2-stack v2-detail-body"><template v-if="entry.trackingAnalytics"><dl class="v2-metric-grid"><div v-for="[label, value] in analyticsMetrics(entry.trackingAnalytics)" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></div></dl><p class="v2-muted">Prima attività: {{ c.formatHistoryDate(entry.trackingAnalytics.firstEventAt) || 'N/D' }} · Ultima: {{ c.formatHistoryDate(entry.trackingAnalytics.lastEventAt) || 'N/D' }} · Picco al minuto: {{ c.formatHistoryDate(entry.trackingAnalytics.peakActivityMinute) || 'N/D' }}</p><section v-if="entry.trackingAnalytics.funnels.length" class="v2-grid v2-grid-2"><article v-for="funnel in entry.trackingAnalytics.funnels" :key="funnel.name"><h4>{{ funnel.name }}</h4><ul class="v2-simple-list"><li v-for="step in funnel.steps" :key="step.key"><span>{{ step.label }}</span><strong>{{ step.countLabel }}</strong></li></ul></article></section><div v-if="entry.trackingAnalytics.segmentBreakdown" class="v2-table-wrap"><table class="v2-table"><caption>Ospiti e tifosi registrati</caption><thead><tr><th scope="col">Interazione</th><th scope="col">Ospiti</th><th scope="col">Registrati</th></tr></thead><tbody><tr v-for="[key, label] in [['submittedVotes', 'Voti'], ['feedbackSubmitted', 'Feedback'], ['sponsorClicks', 'Click sponsor']]" :key="key"><th scope="row">{{ label }}</th><td>{{ numbers(entry.trackingAnalytics.segmentBreakdown.guest[key]) }}</td><td>{{ numbers(entry.trackingAnalytics.segmentBreakdown.registered[key]) }}</td></tr></tbody></table></div><ul v-if="entry.trackingAnalytics.domainBreakdown?.length" class="v2-simple-list"><li v-for="domain in entry.trackingAnalytics.domainBreakdown" :key="domain.domain"><span>{{ domain.domain }}</span><strong>{{ numbers(domain.count) }}</strong></li></ul><ul v-if="entry.trackingAnalytics.topEventNames.length" class="v2-simple-list"><li v-for="top in entry.trackingAnalytics.topEventNames" :key="top.name"><span>{{ top.name }}</span><strong>{{ numbers(top.count) }}</strong></li></ul></template><p v-else class="v2-muted">Analytics non disponibili.</p></div></details>

      <details class="v2-history-section"><summary>Dettaglio delle attività tracciate</summary><div class="v2-stack v2-detail-body"><p v-if="!entry.trackingEvents.length" class="v2-muted">Nessuna attività tracciata.</p><article v-for="track in entry.trackingEvents" :key="track.name" class="v2-tracking-row"><div class="v2-section-heading"><h4>{{ track.nameLabel }}</h4><span class="v2-badge">{{ track.countLabel }}</span></div><p class="v2-muted">Sessioni: {{ track.uniqueSessionsLabel }} · Dispositivi: {{ track.uniqueDevicesLabel }} · Tifosi: {{ track.uniqueFansLabel }}</p><p v-if="track.rangeLabel" class="v2-muted">Ultima attività: {{ track.rangeLabel }}</p><dl v-if="track.details.length" class="v2-data-list"><div v-for="detail in track.details" :key="detail.label"><dt>{{ detail.label }}</dt><dd>{{ detail.value }}</dd></div></dl><ul v-if="track.metadataSamples.length" class="v2-metadata"><li v-for="(sample, index) in track.metadataSamples" :key="index"><code>{{ sample }}</code></li></ul></article></div></details>

      <details class="v2-history-section"><summary>Andamento votazioni</summary><div class="v2-stack v2-detail-body"><p v-if="entry.timelineRange" class="v2-muted">Dal {{ entry.timelineRange.start }} al {{ entry.timelineRange.end }}</p><VoteTrendChart v-if="entry.timelineChart.points.length" :points="entry.timelineChart.points" :start-label="entry.timelineChart.startLabel" :end-label="entry.timelineChart.endLabel" accessible-label="Andamento dei voti ogni 15 minuti" /><p v-if="!entry.timeline.length" class="v2-muted">Nessun intervallo di votazione disponibile.</p><details v-else><summary>Mostra gli intervalli di 15 minuti</summary><ul class="v2-simple-list"><li v-for="bucket in entry.timeline" :key="bucket.start || bucket.rangeLabel"><span>{{ bucket.rangeLabel }}</span><strong>{{ bucket.votesLabel }}</strong></li></ul></details></div></details>
      </div></details>
      <EngagementReportModal v-model="c.engagementReportDialog.visible" :event-id="c.engagementReportDialog.eventId" :event-title="c.engagementReportDialog.eventTitle" :auth-headers="c.authHeaders" @unauthorized="c.handleUnauthorized" @generated="c.onEngagementReportGenerated" />
      <V2Dialog :open="c.purgeDialog.visible" title="Elimina definitivamente l’evento" :busy="c.purgeDialog.isSubmitting" @close="c.closePurgeDialog"><p><strong>{{ c.purgeDialog.event?.title }}</strong></p><p class="v2-muted">Questa operazione rimuove anche tutti i dati collegati. Per confermare inserisci la password del superadmin.</p><form class="v2-stack" @submit.prevent="purge"><label class="v2-field">Password superadmin<input v-model="c.purgeDialog.password" type="password" autocomplete="current-password" required :disabled="c.purgeDialog.isSubmitting" /></label><p v-if="c.purgeDialog.error" class="v2-error" role="alert">{{ c.purgeDialog.error }}</p><div class="v2-toolbar"><button class="v2-button" type="button" :disabled="c.purgeDialog.isSubmitting" @click="c.closePurgeDialog">Annulla</button><button class="v2-button v2-danger" :disabled="!c.purgeDialog.password || c.purgeDialog.isSubmitting">{{ c.purgeDialog.isSubmitting ? 'Eliminazione…' : 'Elimina evento e dati' }}</button></div></form></V2Dialog>
    </template>
  </div>
</template>

